function randHex(n) {
  const chars = '0123456789abcdef';
  let s = '';
  for (let i = 0; i < n * 2; i++) s += chars[Math.floor(Math.random() * 16)];
  return s;
}

function smallHash(str) {
  // FNV-1a-ish — non-cryptographic, just a stable short id derived from content
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

const raw = $input.first().json;
const tallyData = raw.data || raw.body?.data || {};
const fields = tallyData.fields || [];

const fieldMap = {};
for (const f of fields) {
  if (f && f.key) fieldMap[f.key] = f.value;
}

const submissionId = tallyData.submissionId || fieldMap['submission_id'] || 'sub_' + randHex(8);
const stripeSessionId = fieldMap['stripe_checkout_session_id'] || null;

const submission = {
  submission_id: submissionId,
  submitted_at: tallyData.createdAt || new Date().toISOString(),
  stripe_checkout_session_id: stripeSessionId,
  client: {
    legal_name: fieldMap['client_legal_name'] || fieldMap['legal_name'] || '',
    primary_contact_name: fieldMap['client_contact_name'] || fieldMap['primary_contact_name'] || '',
    primary_contact_email: fieldMap['client_email'] || fieldMap['primary_contact_email'] || '',
    role_title: fieldMap['client_role'] || fieldMap['role_title'] || null,
    industry: fieldMap['client_industry'] || fieldMap['industry'] || 'other',
    industry_other_note: fieldMap['client_industry_note'] || fieldMap['industry_other_note'] || null,
    location_count: parseInt(fieldMap['client_locations'] || fieldMap['location_count'] || '1', 10),
    annual_revenue_range: fieldMap['client_revenue'] || fieldMap['annual_revenue_range'] || 'prefer-not-to-say',
  },
  existing_workflows: Array.isArray(fieldMap['existing_workflows']) ? fieldMap['existing_workflows'] : [{
    workflow_name: fieldMap['workflow_name'] || 'Core Ops Workflow',
    current_platform: fieldMap['workflow_platform'] || 'zapier',
    current_platform_other_note: fieldMap['workflow_platform_note'] || null,
    description: fieldMap['workflow_description'] || 'Default workflow details.',
    breaks_per_quarter_estimate: parseInt(fieldMap['workflow_breaks'] || '0', 10),
    maintenance_hours_per_quarter_estimate: parseFloat(fieldMap['workflow_hours'] || '0'),
    touches_pii: fieldMap['workflow_pii'] === true || fieldMap['workflow_pii'] === 'true',
    touches_payment_data: fieldMap['workflow_payments'] === true || fieldMap['workflow_payments'] === 'true',
    touches_health_data: fieldMap['workflow_health'] === true || fieldMap['workflow_health'] === 'true',
    migration_priority: fieldMap['workflow_priority'] || 'medium',
  }],
  integration_requests: Array.isArray(fieldMap['integration_requests']) ? fieldMap['integration_requests'] : [],
  sovereignty: {
    current_primary_cloud: fieldMap['sovereignty_cloud'] || 'none',
    explicit_sovereignty_concern: fieldMap['sovereignty_concern'] === true || fieldMap['sovereignty_concern'] === 'true',
    sovereignty_concern_note: fieldMap['sovereignty_note'] || null,
    regulated_industry_flag: fieldMap['sovereignty_regulated'] === true || fieldMap['sovereignty_regulated'] === 'true',
    regulation_names: Array.isArray(fieldMap['sovereignty_regulations']) ? fieldMap['sovereignty_regulations'] : [],
  },
  budget: {
    audit_tier_purchased: fieldMap['budget_tier'] || 'standard',
    expected_implementation_budget_usd_range: fieldMap['budget_implementation'] || 'no-budget-yet',
    expected_retainer_budget_usd_monthly: fieldMap['budget_retainer'] || 'no-retainer',
    timeline_urgency: fieldMap['budget_urgency'] || 'exploratory',
  },
  biggest_pain_point: fieldMap['pain_point'] || 'No main pain point provided.',
  what_success_looks_like: fieldMap['success_criteria'] || null,
  constraints_or_caveats: fieldMap['constraints'] || null,
};

const errors = [];
if (!submission.client.legal_name || submission.client.legal_name.length < 2) errors.push('client.legal_name must be at least 2 chars.');
if (!submission.client.primary_contact_email || !submission.client.primary_contact_email.includes('@')) errors.push('client.primary_contact_email must be a valid email address.');
if (submission.client.industry === 'other' && !submission.client.industry_other_note) errors.push('industry_other_note is required when industry is other.');
if (submission.biggest_pain_point.length < 10) errors.push('biggest_pain_point must be at least 10 chars.');

if (errors.length > 0) return [{ json: { ok: false, errors, submission_id: submissionId } }];

const ts = new Date().toISOString();
const dateStr = ts.replace(/[:.]/g, '-');
const hash = smallHash(JSON.stringify(submission));
const intakeId = 'intake_' + dateStr + '_' + hash;

const intakeRecord = {
  id: intakeId,
  received_at: ts,
  input_type: 'webhook',
  source: { channel: 'tally', form: 'audit-intake' },
  normalized_payload: { intake_submission: submission },
  quarantine_flags: [],
  routing_hint: '02_reasoning_matrix',
};

return [{ json: { ok: true, intakeId, intakeRecord, summary: {
  client_legal_name: submission.client.legal_name,
  client_email: submission.client.primary_contact_email,
  client_name: submission.client.primary_contact_name,
  industry: submission.client.industry,
  tier: submission.budget.audit_tier_purchased,
  pain_excerpt: submission.biggest_pain_point.slice(0, 200),
}}}];

